/**
 * Personal API tokens: issue, list, revoke and authenticate.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken
 */
import { hashToken, randomToken } from "@/lib/hash";
import { emit, subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const MAX_USABLE_TOKENS = 5;
const SECRET_PREFIX = "tfk_";
const PREFIX_LENGTH = 12;
const DAY_MS = 24 * 60 * 60 * 1000;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  // A write token acts with the member's own role, so it needs `member`.
  if (parsed.scope === "write") {
    assertCan(actor, "issue:create", orgResource(parsed.orgId));
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const used = await apiTokenRepo.countUsableTokens(
    parsed.orgId,
    actor.userId,
    createdAt,
  );
  if (used >= MAX_USABLE_TOKENS) {
    throw new Error(`At most ${MAX_USABLE_TOKENS} active API tokens are allowed`);
  }

  const token = `${SECRET_PREFIX}${randomToken(32)}`;
  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + parsed.expiresInDays * DAY_MS)),
    createdAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
    tokenUserId: apiToken.userId,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const target = userId ?? actor.userId;
  if (target !== actor.userId) assertAdmin(actor);
  return apiTokenRepo.listApiTokens(orgId, target);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await apiTokenRepo.findApiToken(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) assertAdmin(actor);

  return revokeAndAudit(existing, actor.userId);
}

export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const found = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (found === null || found.revokedAt !== null) return null;

  const now = new Date();
  const stamp = toIsoTimestamp(now);
  if (found.expiresAt <= stamp) return null;

  const org = await orgRepo.findOrgById(found.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(found.orgId, found.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.touchLastUsed(found.id, stamp);

  return {
    userId: found.userId,
    orgId: found.orgId,
    role: found.scope === "read" ? "viewer" : member.role,
  };
}

/** Revokes every not-yet-revoked token of a removed member. */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listUnrevokedApiTokens(
      payload.orgId,
      payload.userId,
    );
    for (const apiToken of tokens) {
      await revokeAndAudit(apiToken, payload.actorId);
    }
  });
}

function assertAdmin(actor: Actor): void {
  assertCan(actor, "member:remove", orgResource(actor.orgId));
}

async function revokeAndAudit(
  existing: ApiToken,
  actorId: UserId | null,
): Promise<ApiToken> {
  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.markRevoked(
    existing.orgId,
    existing.id,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) {
    // Lost a race with another revocation; it already recorded the event.
    return requireFound(
      await apiTokenRepo.findApiToken(existing.orgId, existing.id),
      "ApiToken",
      existing.id,
    );
  }

  await emit("api_token.revoked", {
    ...envelope(revoked.orgId, actorId),
    tokenId: revoked.id,
    name: revoked.name,
    tokenUserId: revoked.userId,
  });
  return revoked;
}

// `hasRoleAtLeast` is intentionally not used for gating: `can()` is the single
// authorization entry point.
void hasRoleAtLeast;
